from nlib import *
S=[]
NS="nervous_system"
def O(id,title,kind,sc,sm,b,d,e,f,dy,par,made=(),proc=(),mesh=None,hs=None,sec="13.2",kn=("brain_organization",),rel=(),cert="C1",oq=None,tmpl="anatomy"):
    S.append(N(id,title,kind,tmpl,sc,sm,b,d,e,f,dy,par=par,made=made,proc=proc,mesh=mesh,hs=hs,refs=[("ANP",sec)],kn=kn,rel=rel,cert=cert,oq=oq))
NT=["nervous_tissue"]
O("brain","Brain","organ",0.17,"The brain is the body's control center, a 1.3-1.4 kg organ of about 86 billion neurons.","Your brain handles everything you sense, think, feel and do. It is soft, wrinkled and floats in protective fluid inside the skull.","It has a cerebrum (two hemispheres joined by the corpus callosum), cerebellum and brainstem. The outer folded layer, the cortex, handles complex functions; deeper structures regulate emotion, memory and body state.","Gray matter holds neuronal cell bodies and synapses; white matter is myelinated tracts. The cortex has six layers in most regions and is organized into functionally specialized but interconnected networks. Cerebrospinal fluid, the blood-brain barrier and the glymphatic system protect and clear it.",[("Mass","≈ 1.3-1.4 kg"),("Neurons","≈ 8.6×10^10"),("Power use","≈ 20 W"),("Cortex thickness","≈ 2-4 mm")],"The brain's power draw is about that of a dim light bulb.",[NS],NT+["astrocyte_tissue_note"] if False else NT,["action_potential","synaptic_transmission"],mesh="brain",rel=["cerebellum","brainstem"],kn=("brain_organization","connectome"),oq=["How do patterns of neural activity give rise to subjective experience (the 'hard problem')?","How does the brain represent and store memories at the level of circuits and synapses?"],cert="C1")
for i,t,sc,sm,b,d,e,at,lab,f,dy in [
("frontal_lobe","Frontal lobe",0.08,"The front part of the cortex for planning, decisions and voluntary movement.","The frontal lobe helps you plan, make choices, control impulses and start movements. Speech production relies on regions here (usually left).","Contains the primary motor cortex, premotor areas and the prefrontal cortex. Broca's area supports speech production.","Prefrontal cortex matures into the mid-twenties; dorsolateral PFC supports working memory and executive control, orbitofrontal PFC value computation. Motor homunculus is a somatotopic map along the precentral gyrus.",(0.0,0.02,0.055),"Frontal lobe",[("Share of cortex","≈ 1/3 of cortical surface"),("Key areas","motor, prefrontal, Broca")],"Frontal lobes are among the last brain regions to finish maturing."),
("parietal_lobe","Parietal lobe",0.07,"The upper-middle cortex that processes touch and body position and builds spatial awareness.","This lobe integrates touch, pressure and spatial information so you know where your body and objects are.","The somatosensory cortex lies in the postcentral gyrus; posterior parietal areas guide reaching and attention.","Dorsal visual stream ('where/how') runs through the posterior parietal cortex; lesions can cause neglect or apraxia.",(0.0,0.05,-0.02),"Parietal lobe",[("Key areas","somatosensory cortex, posterior parietal")],"Damage to the right parietal lobe can make a person ignore the left half of the world."),
("temporal_lobe","Temporal lobe",0.07,"The side cortex for hearing, language comprehension and memory.","Sounds, spoken words and faces are processed on the sides of the brain, near the ears.","Contains the auditory cortex, Wernicke's area and the hippocampus deep inside.","Ventral visual stream (object, face recognition) in inferotemporal cortex; medial temporal structures are essential for declarative memory.",(0.05,-0.02,0.0),"Temporal lobe",[("Key areas","auditory cortex, hippocampus")],"Temporal lobe damage can leave people unable to recognize faces."),
("occipital_lobe","Occipital lobe",0.06,"The rear cortex dedicated mostly to vision.","The back of your brain is wired to turn signals from your eyes into what you see.","Primary visual cortex (V1) receives input from the thalamus and maps the visual field.","V1 is retinotopic with cortical magnification of the fovea; later areas V2-V5 handle orientation, color, motion.",(0.0,0.0,-0.07),"Occipital lobe",[("Key areas","V1-V5")],"A blow to the back of the head can make people 'see stars' because it stimulates this region."),
]:
    O(i,t,"structure",sc,sm,b,d,e,f,dy,["brain"],NT+["neuron"][:0],[],hs=("brain",at,lab),sec="13.2")
O("cerebral_cortex","Cerebral cortex","structure",0.004,"The wrinkled outer sheet of the brain where much of perception, thought and voluntary action is computed.","The thin, folded outer layer of your brain. The folds let a large sheet fit inside the skull.","About 16 billion neurons sit in a sheet 2-4 mm thick; folds (gyri and sulci) give it an area of roughly 2,000 cm².","Six-layer neocortical architecture with canonical microcircuits; layer 5 pyramidal neurons project subcortically; cortical areas defined by cytoarchitecture (Brodmann) and multimodal parcellations.",[("Neurons","≈ 1.6×10^10"),("Area (unfolded)","≈ 0.2 m²")],"If you unfolded the cortex it would be about the size of a pillowcase.",["brain"],NT,[],hs=("brain",(0.0,0.06,0.0),"Cerebral cortex"),kn=("brain_organization",))
O("hippocampus","Hippocampus","structure",0.05,"A seahorse-shaped structure needed to form new long-term memories.","The hippocampus helps turn experiences into lasting memories and helps you find your way.","Part of the limbic system, it contains place cells and is central to forming episodic memories.","Trisynaptic circuit (EC-DG-CA3-CA1); LTP at Schaffer collaterals; one of few sites of adult neurogenesis (extent in adult humans is debated).",[("Length","≈ 4-5 cm"),("Shape","Seahorse-like")],"London taxi drivers' studies found enlarged posterior hippocampi, linked to navigation experience.",["brain"],NT,[],hs=("brain",(0.025,-0.02,-0.01),"Hippocampus"),sec="13.2",kn=("memory_learning",),cert="C2",oq=["Does substantial adult hippocampal neurogenesis occur in humans?"])
O("hypothalamus","Hypothalamus","structure",0.015,"A small brain region that regulates temperature, hunger, thirst, sleep and hormones.","This almond-sized region keeps your body's internal settings steady and controls the pituitary gland.","It links the nervous system to the endocrine system via the pituitary stalk.","Contains nuclei such as the suprachiasmatic (circadian clock), paraventricular and supraoptic (oxytocin/vasopressin) and arcuate (feeding, leptin).",[("Mass","≈ 4 g"),("Roles","thermostat, thirst, hunger, sleep")],"It weighs about as much as a grape yet coordinates much of homeostasis.",["brain","endocrine_system"],NT,["hormone_signaling"],hs=("brain",(0.0,-0.02,0.01),"Hypothalamus"),sec="17.3",kn=("endocrine_physiology","sleep_circadian"))
O("corpus_callosum","Corpus callosum","structure",0.1,"The thick band of nerve fibers that connects the brain's two hemispheres.","This bridge lets your left and right brain share information.","About 200 million axons cross here.","Callosotomy for epilepsy produces 'split-brain' effects in specific tasks. Callosal fibers are mainly homotopic.",[("Axons","≈ 2×10^8"),("Length","≈ 10 cm")],"Some people are born without it and live nearly normal lives.",["brain"],NT,[],hs=("brain",(0.0,0.015,0.0),"Corpus callosum"),sec="13.2")
O("thalamus","Thalamus","structure",0.03,"A relay hub that routes sensory signals to the cortex.","Nearly all senses except smell pass through the thalamus on the way to the cortex.","It also takes part in sleep, attention and consciousness.","Thalamic nuclei (LGN, MGN, VPL/VPM) relay and gate sensory information; thalamocortical loops with reticular nucleus generate sleep spindles.",[("Size","≈ 3 cm per side")],"Smell is the only major sense that skips the thalamus's usual relay.",["brain"],NT,[],hs=("brain",(0.0,0.0,0.0),"Thalamus"))
O("amygdala","Amygdala","structure",0.02,"An almond-shaped cluster of nuclei that helps detect threats and tag memories with emotion.","This small region reacts fast to frightening or emotionally important things.","It links with the hypothalamus and brainstem to produce fear responses.","Basolateral and central nuclei mediate fear conditioning; roles in emotion are broader than 'fear center'.",[("Size","≈ 2 cm")],"The name is Greek for almond.",["brain"],NT,[],hs=("brain",(0.025,-0.03,0.015),"Amygdala"),cert="C2")
O("basal_ganglia","Basal ganglia","structure",0.05,"Deep brain nuclei that help select and start movements and habits.","These deep structures help you start and smooth out movement and learn routines.","Loss of dopamine neurons in this system leads to Parkinson's disease.","Cortico-basal ganglia-thalamic loops with direct/indirect pathways; dopamine from the substantia nigra modulates them.",[("Parts","caudate, putamen, globus pallidus")],"The disease-causing loss in Parkinson's affects the substantia nigra.",["brain"],NT,[],hs=("brain",(0.025,0.0,0.01),"Basal ganglia"))
O("cerebellum","Cerebellum","organ",0.1,"The 'little brain' at the back that coordinates movement and balance.","The cerebellum fine-tunes your movements so they are smooth and accurate.","It contains about 80% of the brain's neurons, most of them tiny granule cells.","Compares intended and actual movement via forward models; Purkinje cells are inhibitory output of the cortex; roles in cognition and timing.",[("Mass","≈ 150 g (10% of brain)"),("Neurons","≈ 6.9×10^10")],"It holds around 80% of all neurons in the brain though it is a tenth of the mass.",[NS],NT,["action_potential"],mesh="cerebellum",kn=("brain_organization",))
O("brainstem","Brainstem","organ",0.1,"The stalk connecting brain to spinal cord that controls breathing, heartbeat and wakefulness.","The brainstem runs the basic life functions you never think about.","It includes midbrain, pons and medulla and most cranial nerves.","Reticular formation regulates arousal; medullary respiratory groups (preBötzinger complex) generate rhythm; cardiovascular centers regulate pressure.",[("Length","≈ 7-10 cm"),("Parts","midbrain, pons, medulla")],"Brainstem death is the legal criterion of death in some countries.",[NS],NT,["breathing"],mesh="brainstem")
O("spinal_cord","Spinal cord","organ",0.45,"A cable of nerve tissue running down the spine, carrying signals between brain and body.","The spinal cord is the main data highway between the brain and the body and runs simple reflexes itself.","Dorsal roots carry sensory input, ventral roots carry motor output, with 31 pairs of spinal nerves.","Butterfly-shaped gray matter with dorsal, intermediate, ventral horns; ascending (dorsal column, spinothalamic) and descending (corticospinal) tracts.",[("Length","≈ 42-45 cm"),("Nerve pairs","31"),("Diameter","≈ 1-1.5 cm")],"The spinal cord is only as thick as a finger.",[NS],NT,["action_potential"],mesh="spinal_cord",sec="13.2")
O("peripheral_nerves","Peripheral nerves","structure",1.0,"Cables of axons that connect the CNS to every part of the body.","Nerves are bundles of long nerve fibers that carry commands out and sensations in.","12 cranial and 31 spinal nerve pairs, with myelin sheaths made by Schwann cells for speed.","Fibers classified A-alpha to C by diameter and myelination; conduction velocities from 0.5 to 120 m/s; regeneration is possible in the PNS but not the CNS.",[("Longest nerve (sciatic)","≈ up to 1 m"),("Speed range","≈ 0.5-120 m/s")],"The longest single nerve cells can have axons about a meter long.",[NS],NT,["action_potential"],sec="13.4")
# Eye
for sd,sn in (("l","Left"),("r","Right")):
    O(f"eye_{sd}",f"{sn} eye","organ",0.024,f"The {'left' if sd=='l' else 'right'} eye focuses light onto the retina, where it becomes nerve signals.","The eye is a living camera: light enters through the clear front, is focused, and strikes light-sensing cells at the back.","The cornea does most of the focusing and the lens fine-tunes it. The retina contains rods and cones.","The eye's optical power is ≈ 60 D (cornea ≈ 43 D, lens ≈ 17-20 D at rest); photoreceptors transduce light via the rhodopsin-transducin-PDE cascade, and retinal ganglion cells project to the LGN and superior colliculus.",[("Diameter","≈ 24 mm"),("Rods","≈ 9.2×10^7 (Curcio et al. 1990)"),("Cones","≈ 4.6×10^6 (Curcio et al. 1990)")],"The eye's retina is technically part of the brain, grown out from the embryonic forebrain.",[NS],["epithelial_tissue_simple_note"][:0]+["nervous_tissue","dense_connective_tissue"],["vision"],mesh=f"eye_{sd}",sec="14.1",kn=("vision_eye",))
EY="eye_r"
for i,t,sc,sm,b,d,e,at,lab,dy in [
("cornea","Cornea",0.012,"The clear dome at the front of the eye that does most of its focusing.","The transparent window of the eye. It bends light the most, about two-thirds of the eye's focusing power.","It has no blood vessels, so it gets oxygen straight from the air and tears, and it is very sensitive to touch.","Five layers (epithelium, Bowman's layer, stroma, Descemet's membrane, endothelium); stromal transparency relies on regular collagen fibril spacing (<λ/2).",(0.0,0.0,0.012),"Cornea","Corneas can be transplanted with minimal rejection because they have no blood vessels."),
("iris","Iris",0.012,"The colored ring that controls pupil size.","The iris opens and closes the pupil to adjust how much light enters.","Smooth muscles contract the pupil in bright light (sphincter) or enlarge it in dark (dilator).","Eye color arises from melanin in the anterior stroma; parasympathetic via CN III, sympathetic via the superior cervical ganglion.",(0.0,0.0,0.0105),"Iris","Iris patterns are as unique as fingerprints and used in biometric ID."),
("lens","Lens",0.01,"A clear flexible disc that fine-tunes focus.","The lens changes shape so you can switch between near and far objects.","Ciliary muscles relax or tighten the zonules, making the lens thinner or rounder (accommodation).","Lens fibers lose organelles and contain crystallins at ≈ 35% by weight; presbyopia arises from stiffening and loss of accommodation after ≈ 45.",(0.0,0.0,0.005),"Lens","Lens crystallin proteins last a lifetime without replacement."),
("vitreous_humor","Vitreous humor",0.016,"A clear gel filling the main chamber of the eye.","A jelly that keeps the eyeball round.","About 99% water with collagen and hyaluronan.","Age-related syneresis leads to 'floaters' and posterior vitreous detachment.",(0.0,0.0,-0.002),"Vitreous humor","Floaters are shadows of vitreous fibers on your retina."),
("retina","Retina",0.0003,"The light-sensitive layer at the back of the eye.","The retina turns images into nerve signals using millions of light-sensing cells.","Contains rods, cones, and neurons that begin image processing before the signal leaves the eye.","Layers: photoreceptors, bipolar, horizontal, amacrine and ganglion cells; image is inverted; thickness ≈ 0.2-0.5 mm.",(0.0,0.0,-0.011),"Retina","The retina processes information before sending it to the brain."),
("fovea","Fovea",0.0015,"The tiny pit in the retina with the sharpest vision.","Where you look directly, light lands on the fovea, packed with cones.","It supplies the high-resolution color vision you use for reading.","Foveola has ≈ 150,000-200,000 cones/mm² with no rods; one-to-one connections to ganglion cells.",(0.0,0.0,-0.0115),"Fovea","Only about 1-2 degrees of your visual field is truly sharp."),
("optic_nerve","Optic nerve",0.05,"The bundle of about a million fibers carrying visual signals to the brain.","The cable from the eye to the brain.","It leaves at the optic disc, which has no photoreceptors, creating the blind spot.","Myelinated by oligodendrocytes (CNS tract); ≈ 1.2×10^6 axons; partial decussation at the optic chiasm.",(0.004,0.0,-0.0135),"Optic nerve","Each of your eyes has a blind spot your brain fills in."),
]:
    O(i,t,"structure",sc,sm,b,d,e,[("Role",sm.rstrip('.'))],dy,[EY],["nervous_tissue"] if i in("retina","optic_nerve") else ["dense_connective_tissue"] if i in ("cornea","vitreous_humor") else ["smooth_muscle_tissue"] if i=="iris" else ["epithelial_tissue_simple_note"][:0]+["dense_connective_tissue"] if False else (["smooth_muscle_tissue"] if i=="iris" else ["dense_connective_tissue"] if i!="lens" else ["epithelial_tissue"]),["vision"],hs=(EY,at,lab),sec="14.1",kn=("vision_eye",))
